<?phpnamespace App\Http\Controllers;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;use App\Services\ActiveContextService;
use Illuminate\Http\Request;
use App\Services\Permissions\ProfilePermissionService;class WorkshopController extends Controller{
    /** Dados somente-leitura para o painel de manutenção da Oficina. */
    public function maintenanceDashboard(Request $request)
    {
        $user = $request->user(); $location = app(ActiveContextService::class)->activeLocation($user);
        if (! $location) abort(422, 'Selecione uma unidade para continuar.');
        $scope = ['tenant_id'=>$user->tenant_id, 'division_id'=>session('active_division_id'), 'location_id'=>$location->id, 'module'=>'fleet'];
        abort_unless(app(ProfilePermissionService::class)->allows($user, 'maintenance.view', $scope), 403);
        $period = $request->input('period', 'last_30_days'); $today = now()->startOfDay();
        [$start,$end,$periodLabel] = match ($period) {'current_month'=>[$today->copy()->startOfMonth(),$today->copy()->endOfMonth(),'Mês atual'],'last_90_days'=>[$today->copy()->subDays(90),$today->copy()->endOfDay(),'Últimos 90 dias'],'current_year'=>[$today->copy()->startOfYear(),$today->copy()->endOfYear(),'Ano atual'],default=>[$today->copy()->subDays(30),$today->copy()->endOfDay(),'Últimos 30 dias']};
        $base=DB::table('maintenance_records as mr')->join('vehicles as v','v.id','=','mr.vehicle_id')->leftJoin('procedures as p','p.id','=','mr.procedure_id')->where('mr.tenant_id',$user->tenant_id)->where('v.tenant_id',$user->tenant_id)->where('v.division_id',session('active_division_id'))->where('v.location_id',$location->id)->whereNull('mr.deleted_at');
        $permissions=app(ProfilePermissionService::class);$canViewCosts=$permissions->allows($user,'maintenance.view_costs',$scope);$canViewCancelled=$permissions->allows($user,'maintenance.view_cancellation_details',$scope);$active=(clone $base)->whereNull('mr.cancelled_at');$inPeriod=(clone $active)->whereBetween('mr.created_at',[$start,$end]);$open=(clone $active)->where('mr.workflow_status','open');$completed=(clone $inPeriod)->where('mr.workflow_status','closed');
        $withDates=(clone $completed)->whereNotNull('mr.started_at')->whereNotNull('mr.finished_at')->get(['mr.started_at','mr.finished_at']);$averageDowntime=$withDates->isEmpty()?null:round($withDates->avg(fn($r)=>\Carbon\Carbon::parse($r->started_at)->diffInMinutes(\Carbon\Carbon::parse($r->finished_at))/1440),1);
        $status=[['key'=>'open','label'=>'Abertas','count'=>(clone $inPeriod)->where('mr.workflow_status','open')->count()],['key'=>'in_progress','label'=>'Em andamento','count'=>(clone $inPeriod)->where('mr.workflow_status','open')->where('mr.service_status','in_progress')->count()],['key'=>'closed','label'=>'Concluídas','count'=>(clone $completed)->count()]];if($canViewCancelled)$status[]=['key'=>'cancelled','label'=>'Canceladas','count'=>(clone $base)->whereNotNull('mr.cancelled_at')->whereBetween('mr.created_at',[$start,$end])->count()];
        $typeExpression = "COALESCE(NULLIF(mr.maintenance_category, ''), NULLIF(mr.maintenance_type, ''), 'other')";
        $types = (clone $inPeriod)->selectRaw($typeExpression . " as type, COUNT(*) as count")->groupByRaw($typeExpression)->orderByDesc('count')->get();$trend = match ($period) {
            'current_year' => (clone $inPeriod)->selectRaw("DATE_FORMAT(mr.created_at, '%Y-%m') as bucket, DATE_FORMAT(mr.created_at, '%m/%Y') as label, COUNT(*) as value")->groupByRaw("DATE_FORMAT(mr.created_at, '%Y-%m'), DATE_FORMAT(mr.created_at, '%m/%Y')")->orderBy('bucket')->get(),
            'last_90_days' => (clone $inPeriod)->selectRaw("YEARWEEK(mr.created_at, 1) as bucket, DATE_FORMAT(MIN(mr.created_at), '%d/%m') as label, COUNT(*) as value")->groupByRaw('YEARWEEK(mr.created_at, 1)')->orderBy('bucket')->get(),
            default => (clone $inPeriod)->selectRaw("DATE(mr.created_at) as bucket, DATE_FORMAT(mr.created_at, '%d/%m') as label, COUNT(*) as value")->groupByRaw("DATE(mr.created_at), DATE_FORMAT(mr.created_at, '%d/%m')")->orderBy('bucket')->get(),
        };
        
        $topVehicles=(clone $inPeriod)->select('mr.vehicle_id','v.name','v.plate',DB::raw('COUNT(*) as count'))->groupBy('mr.vehicle_id','v.name','v.plate')->orderByDesc('count')->limit(10)->get();$topCosts=$canViewCosts?(clone $inPeriod)->select('mr.vehicle_id','v.name','v.plate',DB::raw('SUM(mr.total_cost) as total_cost'))->groupBy('mr.vehicle_id','v.name','v.plate')->orderByDesc('total_cost')->limit(10)->get():collect();$procedures=(clone $inPeriod)->selectRaw("COALESCE(p.name, 'Sem procedimento') as label, COUNT(*) as count")->groupBy('p.name')->orderByDesc('count')->limit(10)->get();
        $oldOpen=(clone $open)->select('mr.id','mr.vehicle_id','mr.started_at','mr.created_at','mr.service_status','v.name','v.plate')->orderByRaw('COALESCE(mr.started_at, mr.created_at) ASC')->limit(10)->get()->map(function($r){$opened=\Carbon\Carbon::parse($r->started_at??$r->created_at);$r->opened_at=$opened->format('d/m/Y H:i');$r->stopped_days=$opened->copy()->startOfDay()->diffInDays(now()->startOfDay());return $r;});
        return response()->json(['period'=>$period,'period_label'=>$periodLabel,'permissions'=>['view_costs'=>$canViewCosts,'view_cancelled'=>$canViewCancelled],'summary'=>['open_orders'=>(clone $open)->count(),'vehicles_in_maintenance'=>(clone $open)->distinct()->count('mr.vehicle_id'),'completed_orders'=>(clone $completed)->count(),'average_downtime_days'=>$averageDowntime,'total_cost'=>$canViewCosts?(float)(clone $inPeriod)->sum('mr.total_cost'):null],'status'=>$status,'types'=>$types,'trend'=>$trend,'top_vehicles'=>$topVehicles,'top_vehicles_by_cost'=>$topCosts,'procedures'=>$procedures,'old_open_orders'=>$oldOpen]);
    }

    public function index()    {        $tenantId = auth()->user()->tenant_id ?? 1;        $activeDivisionId = session('active_division_id');        $activeLocation = app(ActiveContextService::class)            ->activeLocation(auth()->user());        if (! $activeLocation) {            return redirect()                ->route('portal')                ->with(                    'warning',                    'Selecione uma unidade para continuar.'                );        }        /*        |--------------------------------------------------------------------------        | ESTOQUE        |--------------------------------------------------------------------------        */        $lowStockItems = collect();        $lowStockCount = 0;        $latestStockMovements = collect();        if (Schema::hasTable('stock_items')) {            $lowStockItems = DB::table('stock_items')                ->where('tenant_id', $tenantId)                ->where('location_id', $activeLocation->id)                ->where('active', 1)                ->whereColumn('quantity', '<=', 'minimum_quantity')                ->orderBy('quantity')                ->limit(5)                ->get();            $lowStockCount = DB::table('stock_items')                ->where('tenant_id', $tenantId)                ->where('location_id', $activeLocation->id)                ->where('active', 1)                ->whereColumn('quantity', '<=', 'minimum_quantity')                ->count();        }        if (Schema::hasTable('stock_movements')) {            $latestStockMovements = DB::table('stock_movements')                ->leftJoin('stock_items', 'stock_items.id', '=', 'stock_movements.stock_item_id')                ->where('stock_movements.tenant_id', $tenantId)                ->where('stock_movements.location_id', $activeLocation->id)                ->select(                    'stock_movements.*',                    'stock_items.name as item_name',                    'stock_items.unit as item_unit'                )                ->latest('stock_movements.created_at')                ->limit(5)                ->get();        }        /*        |--------------------------------------------------------------------------        | PNEUS        |--------------------------------------------------------------------------        */        $tiresAttention = collect();        $tiresAttentionCount = 0;        $latestTireEntries = collect();        if (            Schema::hasTable('tires') &&            Schema::hasTable('tire_measurements') &&            Schema::hasTable('tire_retreads')        ) {            $latestMeasurementSubquery = DB::table('tire_measurements as measurement')                ->select('measurement.*')                ->where('measurement.tenant_id', $tenantId)                ->whereNull('measurement.cancelled_at')                ->whereNotExists(function ($query) {                    $query                        ->select(DB::raw(1))                        ->from('tire_measurements as newer_measurement')                        ->whereColumn('newer_measurement.tenant_id', 'measurement.tenant_id')                        ->whereColumn('newer_measurement.tire_id', 'measurement.tire_id')                        ->whereNull('newer_measurement.cancelled_at')                        ->where(function ($query) {                            $query                                ->whereColumn('newer_measurement.measured_at', '>', 'measurement.measured_at')                                ->orWhere(function ($query) {                                    $query                                        ->whereColumn('newer_measurement.measured_at', 'measurement.measured_at')                                        ->whereColumn('newer_measurement.id', '>', 'measurement.id');                                });                        });                });            $latestRetreadSubquery = DB::table('tire_retreads as retread')                ->select('retread.*')                ->where('retread.tenant_id', $tenantId)                ->whereNull('retread.cancelled_at')                ->whereNotExists(function ($query) {                    $query                        ->select(DB::raw(1))                        ->from('tire_retreads as newer_retread')                        ->whereColumn('newer_retread.tenant_id', 'retread.tenant_id')                        ->whereColumn('newer_retread.tire_id', 'retread.tire_id')                        ->whereNull('newer_retread.cancelled_at')                        ->where(function ($query) {                            $query                                ->whereColumn('newer_retread.retreaded_at', '>', 'retread.retreaded_at')                                ->orWhere(function ($query) {                                    $query                                        ->whereColumn('newer_retread.retreaded_at', 'retread.retreaded_at')                                        ->whereColumn('newer_retread.id', '>', 'retread.id');                                });                        });                });            $currentTreadSql = "                CASE                    WHEN latest_measurements.id IS NOT NULL                        AND (                            latest_retreads.id IS NULL                            OR latest_measurements.measured_at > latest_retreads.retreaded_at                        )                        THEN latest_measurements.minimum_tread                    WHEN latest_retreads.id IS NOT NULL                        THEN latest_retreads.new_tread_depth                    ELSE tires.initial_tread_depth                END            ";            $tiresAttentionBase = DB::table('tires')                ->leftJoinSub($latestMeasurementSubquery, 'latest_measurements', function ($join) {                    $join->on('latest_measurements.tire_id', '=', 'tires.id');                })                ->leftJoinSub($latestRetreadSubquery, 'latest_retreads', function ($join) {                    $join->on('latest_retreads.tire_id', '=', 'tires.id');                })                ->where('tires.tenant_id', $tenantId)                ->where('tires.location_id', $activeLocation->id)                ->whereNull('tires.cancelled_at')                ->where(function ($query) use ($currentTreadSql) {                    $query                        ->whereRaw("{$currentTreadSql} <= tires.warning_tread_depth")                        ->orWhere('tires.status', 'maintenance')                        ->orWhere('tires.status', 'discarded');                })                ->select(                    'tires.id',                    'tires.code',                    'tires.brand',                    'tires.model',                    'tires.size',                    'tires.status',                    'tires.initial_tread_depth',                    'tires.warning_tread_depth',                    'tires.critical_tread_depth',                    'latest_measurements.vehicle_id',                    'latest_measurements.position_code',                    'latest_measurements.measured_at',                    DB::raw("{$currentTreadSql} as minimum_tread"),                    'latest_measurements.average_tread',                    'latest_measurements.vehicle_km',                    DB::raw("{$currentTreadSql} as current_tread_depth")                );            $tiresAttentionCount = (clone $tiresAttentionBase)->count();            $tiresAttention = $tiresAttentionBase                ->orderByRaw("{$currentTreadSql} IS NULL")                ->orderByRaw($currentTreadSql)                ->limit(5)                ->get();        }        if (Schema::hasTable('tire_entries')) {            $latestTireEntries = DB::table('tire_entries')                ->where('tenant_id', $tenantId)                ->where('location_id', $activeLocation->id)                ->whereNull('cancelled_at')                ->latest('created_at')                ->limit(5)                ->get();        }        /*        |--------------------------------------------------------------------------        | PROCEDIMENTOS        |--------------------------------------------------------------------------        */        $proceduresPreview = collect();        $proceduresCount = 0;        if (Schema::hasTable('procedures')) {            $proceduresPreview = DB::table('procedures')                ->where('tenant_id', $tenantId)                ->where('location_id', $activeLocation->id)                ->latest('created_at')                ->limit(5)                ->get();            $proceduresCount = DB::table('procedures')                ->where('tenant_id', $tenantId)                ->where('location_id', $activeLocation->id)                ->count();        }        /*        |--------------------------------------------------------------------------        | MANUTENÇÕES EM ANDAMENTO        |--------------------------------------------------------------------------        */                $vehiclesInMaintenance = collect();        $maintenanceVehiclesCount = 0;                if (            Schema::hasTable('vehicles') &&            Schema::hasTable('maintenance_records')        ) {            $openMaintenancesQuery = DB::table('maintenance_records')                ->join(                    'vehicles',                    'vehicles.id',                    '=',                    'maintenance_records.vehicle_id'                )                ->leftJoin(                    'procedures',                    'procedures.id',                    '=',                    'maintenance_records.procedure_id'                )                ->where(                    'maintenance_records.tenant_id',                    $tenantId                )                ->where(                    'vehicles.tenant_id',                    $tenantId                )                ->where(                    'vehicles.location_id',                    $activeLocation->id                )                ->where(                    'vehicles.division_id',                    $activeDivisionId                )                ->where(                    'maintenance_records.workflow_status',                    'open'                )                ->whereNull(                    'maintenance_records.cancelled_at'                )                ->whereNull('maintenance_records.deleted_at')                ->select([                    'maintenance_records.id as maintenance_id',                    'maintenance_records.vehicle_id',                    'maintenance_records.procedure_id',                    'maintenance_records.maintenance_type',                    'maintenance_records.workflow_status',                    'maintenance_records.service_status',                    'maintenance_records.started_at',                    'maintenance_records.created_at as maintenance_created_at',                    'maintenance_records.total_cost',                    'maintenance_records.provider_name',                    'maintenance_records.reason',                    'vehicles.name as vehicle_name',                    'vehicles.plate as vehicle_plate',                    'vehicles.type as vehicle_type',                    'vehicles.operational_status',                    'procedures.name as procedure_name',                ]);                    $vehiclesInMaintenance = (clone $openMaintenancesQuery)                ->orderByRaw(                    'COALESCE(                        maintenance_records.started_at,                        maintenance_records.created_at                    ) ASC'                )                ->limit(6)                ->get();                    $maintenanceVehiclesCount = (clone $openMaintenancesQuery)                ->distinct()                ->count('maintenance_records.vehicle_id');        }        return view('workshop.index', compact(            'lowStockItems',            'lowStockCount',            'latestStockMovements',            'tiresAttention',            'tiresAttentionCount',            'latestTireEntries',            'proceduresPreview',            'proceduresCount',            'vehiclesInMaintenance',            'maintenanceVehiclesCount'        ));    }}